import React, { useState, useRef } from "react";
import { 
  X, User, Truck, AlertCircle, BookOpen, 
  CheckCircle, Activity, MapPin, Database, Award
} from "lucide-react";
import ScheduleTab from "../tabs/ScheduleTab";
import ReportsTab from "../tabs/ReportsTab";
import TrainingTab from "../tabs/TrainingTab";

const WorkerDashboard = () => {
  const [activeTab, setActiveTab] = useState("schedule");
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [selectedReport, setSelectedReport] = useState(null);
  const scrollRef = useRef(null);

  const reportData = {
    'LOC_04': {
      id: 'REP-772',
      title: 'Waste Overflow',
      loc: 'Sector 4',
      citizen: 'A. Smith',
      time: '10:45 AM',
      description: 'The bin at the corner of 5th Ave is completely overflowing. Plastic bottles are everywhere on the sidewalk.',
      img: 'https://images.unsplash.com/photo-1605600611284-19561ad7ddf0?q=80&w=600',
    },
    'LOC_15': {
      id: 'REP-801',
      title: 'Illegal Dumping',
      loc: 'East Gate',
      citizen: 'P. Kumar',
      time: '09:20 AM',
      description: 'Someone left old furniture and construction debris near the park entrance.',
      img: 'https://images.unsplash.com/photo-1530587191325-3db32d826c18?q=80&w=600',
    }
  };

  const handleOpenReport = (locationId) => {
    if (reportData[locationId]) setSelectedReport(reportData[locationId]);
  };

  const tabs = [
    { id: "schedule", label: "Tasks", icon: <Truck size={24} />, title: "Todays Schedule" },
    { id: "reports", label: "Issues", icon: <AlertCircle size={24} />, title: "Issues" },
    { id: "training", label: "Learn", icon: <BookOpen size={24} />, title: "Learn" },
  ];

  const scrollToTab = (tabId) => {
    const index = tabs.findIndex(t => t.id === tabId);
    setActiveTab(tabId);
    set
    scrollRef.current.scrollTo({ left: index * window.innerWidth, behavior: "smooth" });
  };

  const handleScroll = () => {
    if (scrollRef.current) {
      const index = Math.round(scrollRef.current.scrollLeft / window.innerWidth);
      if (tabs[index] && tabs[index].id !== activeTab) {
        setActiveTab(tabs[index].id);
      }
    }
  };

  return (
    <div className="h-screen bg-[#FDFAD8] font-sans relative overflow-hidden perspective-1000">

      {/* 1. STATIC PROFILE TRIGGER (FIXED IN TOP RIGHT) */}
      <div className="fixed top-12 right-10 z-[110]">
        <button 
          onClick={() => setIsProfileOpen(true)} 
          className="bg-[#47510B] p-1.5 pr-6 rounded-2xl flex items-center gap-3 border-2 border-white shadow-xl text-[#CAD23C] active:scale-90 transition-all pointer-events-auto"
        >
          <div className="w-10 h-10 rounded-xl bg-[#CAD23C] flex items-center justify-center text-[#47510B] shadow-inner">
            <User size={22} strokeWidth={3} />
          </div>
          <span className="font-black text-[12px] uppercase tracking-widest font-mono">Profile</span>
        </button>
      </div>

      {/* --- REPORT DETAIL MODAL --- */}
      {selectedReport && (
        <div className="fixed inset-0 z-[300] flex items-center justify-center p-4 bg-[#47510B]/95 backdrop-blur-xl animate-in fade-in duration-300">
          <div className="bg-[#FDFAD8] w-full max-w-sm h-[600px] rounded-[50px] border-[8px] border-white overflow-hidden animate-slide-up flex flex-col shadow-2xl">
            <div className="h-44 min-h-[176px] w-full relative shrink-0">
              <img src={selectedReport.img} alt="Evidence" className="w-full h-full object-cover" />
              <button onClick={() => setSelectedReport(null)} className="absolute top-4 right-4 w-10 h-10 bg-white rounded-full flex items-center justify-center text-[#AB1717] shadow-xl"><X size={20} strokeWidth={3} /></button>
              <div className="absolute bottom-4 left-4 bg-[#AB1717] text-white text-[9px] font-black px-3 py-1 rounded-full uppercase tracking-tighter">
                Evidence_File_{selectedReport.id.split('-')[1]}
              </div>
            </div>
            <div className="p-8 flex-1 overflow-y-auto no-scrollbar flex flex-col">
              <h4 className="text-2xl font-black text-[#47510B] uppercase italic leading-tight">{selectedReport.title}</h4>
              <div className="flex items-center gap-2 mt-1 mb-6 opacity-40"><MapPin size={12} /><span className="text-[10px] font-black uppercase tracking-widest">{selectedReport.loc}</span></div>
              <div className="p-5 bg-white rounded-3xl border-2 border-[#47510B]/10 italic text-sm text-[#47510B]/80 leading-relaxed shadow-inner mb-6">"{selectedReport.description}"</div>
              <button onClick={() => setSelectedReport(null)} className="mt-auto w-full py-5 bg-[#47510B] text-[#CAD23C] rounded-[25px] font-black uppercase text-sm shadow-xl flex items-center justify-center gap-3 active:scale-95 transition-all"><CheckCircle size={18} /> Mark as Resolved</button>
            </div>
          </div>
        </div>
      )}

      {/* --- PROFILE LAYER (READ-ONLY) --- */}
<div className={`absolute inset-0 z-[200] transition-all duration-1000 ease-[cubic-bezier(0.23,1,0.32,1)] flex items-center justify-center p-4 md:p-12 ${isProfileOpen ? "opacity-100 scale-100 translate-z-0" : "opacity-0 scale-125 translate-z-[-500px] pointer-events-none"}`}>
  <div className="w-full h-full bg-[#FDFAD8] rounded-[60px] shadow-2xl relative overflow-hidden flex flex-col border-[12px] border-white">

    {/* Close Button */}
    <button onClick={() => setIsProfileOpen(false)} className="absolute top-6 right-6 w-12 h-12 bg-white rounded-full flex items-center justify-center text-[#47510B] hover:rotate-90 transition-transform shadow-xl z-50 border-2 border-[#47510B]/5">
      <X size={24} />
    </button>

    <div className="flex-1 overflow-y-auto no-scrollbar p-8 md:p-16">

      {/* HEADER SECTION */}
      <div className="flex flex-col md:flex-row justify-between items-start gap-8 mb-12">
        <div>
          <h3 className="text-5xl font-black italic text-[#47510B] uppercase tracking-tighter leading-none mb-4">
            Marcus<br/><span className="text-[#CAD23C]">Sterling.</span>
          </h3>
          <div className="flex gap-2">
            <span className="px-3 py-1 bg-[#47510B] text-[#CAD23C] rounded-lg text-[9px] font-black uppercase tracking-widest">UNIT_7729</span>
            <span className="px-3 py-1 border-2 border-[#47510B] text-[#47510B] rounded-lg text-[9px] font-black uppercase tracking-widest">SECTOR_04</span>
          </div>
        </div>

        {/* STATS */}
        <div className="flex gap-3">
          <div className="bg-[#CAD23C] px-6 py-4 rounded-[25px] border-2 border-[#47510B] text-center shadow-[4px_4px_0_0_#47510B]">
            <p className="text-[8px] font-black opacity-60 uppercase text-[#47510B]">Badges</p>
            <p className="text-xl font-black italic text-[#47510B]">12</p>
          </div>
          <div className="bg-[#AB1717] px-6 py-4 rounded-[25px] border-2 border-[#47510B] text-center text-white shadow-[4px_4px_0_0_#47510B]">
            <p className="text-[8px] font-black opacity-60 uppercase text-[#FDFAD8]">Strikes</p>
            <p className="text-xl font-black italic text-[#FDFAD8]">01</p>
          </div>
        </div>
      </div>

      {/* PERSONAL DETAILS */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-12">
        <div className="p-5 bg-white rounded-[30px] border-2 border-[#47510B]/10">
          <p className="text-[9px] font-black text-[#A1AED1] uppercase mb-1 tracking-widest font-mono">Registry_Email</p>
          <p className="font-bold text-[#47510B] text-sm lowercase">m.sterling@trash2track.gov</p>
        </div>
        <div className="p-5 bg-white rounded-[30px] border-2 border-[#47510B]/10">
          <p className="text-[9px] font-black text-[#A1AED1] uppercase mb-1 tracking-widest font-mono">Comm_Line</p>
          <p className="font-bold text-[#47510B] text-sm">+44 7700 90001</p>
        </div>
        <div className="p-5 bg-white rounded-[30px] border-2 border-[#47510B]/10">
          <p className="text-[9px] font-black text-[#A1AED1] uppercase mb-1 tracking-widest font-mono">License_Class</p>
          <p className="font-bold text-[#47510B] text-sm uppercase">HGV / Heavy_Lift</p>
        </div>
      </div>

      {/* HISTORY SECTION */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-10">

        {/* PICKUP ARCHIVE */}
        <div>
          <h4 className="flex items-center gap-2 text-xl font-black italic text-[#47510B] uppercase tracking-tighter mb-4 px-2">
            <Truck size={18} /> Pickup_Archive
          </h4>
          <div className="max-h-[300px] overflow-y-auto pr-3 space-y-2 no-scrollbar">
            {[1, 2, 3, 4, 5, 6].map((i) => (
              <div key={i} className={`p-4 rounded-[20px] border-2 border-[#47510B] flex items-center justify-between transition-all ${i <= 3 ? 'bg-white shadow-[4px_4px_0_0_#CAD23C] opacity-100' : 'bg-white/40 border-dashed opacity-50'}`}>
                <div className="flex items-center gap-3">
                  <div className="w-8 h-8 rounded-lg bg-[#FDFAD8] flex items-center justify-center">
                    <CheckCircle size={14} className="text-[#47510B]" />
                  </div>
                  <div>
                    <p className="text-[10px] font-black text-[#47510B] uppercase">Sector_0{i}_Node</p>
                    <p className="text-[8px] font-bold opacity-30 italic">MAR 1{i}_2026</p>
                  </div>
                </div>
                <span className="text-[8px] font-black bg-[#47510B] text-[#CAD23C] px-2 py-0.5 rounded uppercase tracking-tighter">Verified</span>
              </div>
            ))}
          </div>
        </div>

        {/* RESOLUTION LOGS */}
        <div>
          <h4 className="flex items-center gap-2 text-xl font-black italic text-[#47510B] uppercase tracking-tighter mb-4 px-2">
            <Activity size={18} /> Resolution_Logs
          </h4>
          <div className="max-h-[300px] overflow-y-auto pr-3 space-y-2 no-scrollbar">
            {[1, 2, 3, 4, 5, 6].map((i) => (
              <div key={i} className={`p-4 rounded-[20px] border-2 border-[#47510B] flex items-center justify-between transition-all ${i <= 3 ? 'bg-white shadow-[4px_4px_0_0_#AB1717] opacity-100' : 'bg-white/40 border-dashed opacity-50'}`}>
                <div className="flex items-center gap-3">
                  <div className="w-8 h-8 rounded-lg bg-[#FDFAD8] flex items-center justify-center text-[#AB1717]">
                    <AlertCircle size={14} />
                  </div>
                  <div>
                    <p className="text-[10px] font-black text-[#47510B] uppercase">Issue_Fixed_0{i}</p>
                    <p className="text-[8px] font-bold opacity-30 italic">MAR 0{i}_2026</p>
                  </div>
                </div>
                <div className="w-2 h-2 rounded-full bg-[#CAD23C]" />
              </div>
            ))}
          </div>
        </div>

      </div>
    </div>
  </div>
</div>

      {/* --- MAIN SWIPEABLE CONTENT LAYER --- */}
      <div className={`h-full w-full transition-all duration-1000 ease-[cubic-bezier(0.23,1,0.32,1)] flex flex-col ${isProfileOpen ? "scale-50 opacity-0 -translate-x-full pointer-events-none" : "scale-100 opacity-100"}`}>
        <main ref={scrollRef} onScroll={handleScroll} className="flex-1 flex h-full overflow-x-auto snap-x snap-mandatory no-scrollbar">
          {tabs.map((tab) => (
            <section key={tab.id} className="min-w-full h-full snap-start flex flex-col items-center overflow-y-auto pt-14 px-6 no-scrollbar">
              <div className="w-full max-w-md flex flex-col">
                {/* Tab Title swipes with content */}
                <h2 className="text-3xl font-black italic text-[#47510B] uppercase tracking-tighter mb-10 text-left">
                  {tab.title}<span className="text-[#CAD23C]">.</span>
                </h2>
                {/* Lists are center-aligned within the max-w-md container */}
                <div className="flex flex-col items-center w-full">
                  {tab.id === 'schedule' && <ScheduleTab onViewReport={handleOpenReport} />}
                  {tab.id === 'reports' && <ReportsTab onSelectReport={setSelectedReport} />}
                  {tab.id === 'training' && <TrainingTab />}
                </div>
                <div className="h-48 shrink-0 w-full" /> 
              </div>
            </section>
          ))}
        </main>

        {/* STATIC FOOTER NAV */}
        <footer className="fixed bottom-10 left-1/2 -translate-x-1/2 z-[110]">
          <nav className="bg-[#47510B]/80 backdrop-blur-2xl border border-white/30 px-4 py-3 rounded-[40px] shadow-[0_20px_50px_rgba(71,81,11,0.3)] flex items-center gap-2">
            {tabs.map((tab) => (
              <button key={tab.id} onClick={() => scrollToTab(tab.id)} className={`flex items-center gap-3 px-8 py-4 rounded-[30px] transition-all duration-500 ${activeTab === tab.id ? "bg-[#CAD23C] text-[#47510B] shadow-lg scale-110" : "text-white/40"}`}>
                <div className="transition-transform duration-500">{tab.icon}</div>
                {activeTab === tab.id && <span className="text-[11px] font-[1000] uppercase tracking-[0.2em]">{tab.label}</span>}
              </button>
            ))}
          </nav>
        </footer>
      </div>
    </div>
  );
};

export default WorkerDashboard;
